class Solution {static const long long MOD=1000000007;long long C2(long long x){return x<2?0:x*(x-1)/2;}public:int subsequencesWithMiddleMode(vector<int>&nums){int n=nums.size();unordered_map<int,long long>L,R;for(int x:nums)R[x]++;long long ans=0;for(int i=0;i<n;i++){int x=nums[i];R[x]--;long long l=i,r=n-i-1,a=L[x],b=R[x],c=l-a,d=r-b;long long ways=0;for(int p=0;p<=2;p++)for(int q=0;q<=2;q++)if(p+q>=2){long long v=(p==0?1:p==1?a:C2(a))*(q==0?1:q==1?b:C2(b));v*= (2-p==0?1:2-p==1?c:C2(c));v*= (2-q==0?1:2-q==1?d:C2(d));ways=(ways+v)%MOD;}
// Exactly one additional x, with the three remaining positions occupied by three distinct non-x values.
// x chosen on left: 1 other left + 2 right; x chosen on right: 2 left + 1 other right.
long long badA=0,badB=0;for(auto &kv:L)if(kv.first!=x){long long u=kv.second,v=R[kv.first];badA+=u*C2(v)+u*v*(d-v);badB+=C2(u)*v+u*v*(c-u);}long long pairL=0,pairR=0;for(auto &kv:L)if(kv.first!=x)pairL+=C2(kv.second);for(auto &kv:R)if(kv.first!=x)pairR+=C2(kv.second);
// For left-x: one other left, two right. Bad triples = two right equal OR one left equals one right.
long long goodA=c*C2(d)-c*pairR;for(auto &kv:L)if(kv.first!=x){long long u=kv.second,v=R[kv.first];goodA-=u*v*(d-v);}
// For right-x: two left, one other right.
long long goodB=C2(c)*d-pairL*d;for(auto &kv:R)if(kv.first!=x){long long u=L[kv.first],v=kv.second;goodB-=v*u*(c-u);}
ways=(ways+a*goodA+b*goodB)%MOD;ans=(ans+ways)%MOD;L[x]++;}return (ans+MOD)%MOD;}};
